// Long readouts in the report runtime (FEA-CH-41, FEA-CH-42, FEA-CH-56). A 60-series calendar
// line and a scatter plot with 60 detail fields, each readout taller than the 900 px viewport,
// are generated by the release CLI and inspected by keyboard at desktop and phone widths.
// Checked for each:
// - Inside the chart: the readout stays at least 8 px inside where it may sit, within the
//   viewport and any clipping ancestor: the figure on a chart narrower than 480 px, the canvas
//   otherwise; and its full list is the model's.
// - Page Down and Page Up: they scroll the readout to its last line and back, keeping the
//   selection and the page position.
// - Next observation: it opens at its first line.
// - No readout: Page Down scrolls the page as usual.
import assert from 'node:assert/strict';
import { harness, watchErrors } from './browser-harness.ts';
import { reports, settle } from './report-runtime.ts';
import type { Locator } from 'playwright';

const fence = (value: object) => `\n\`\`\`chart\n${JSON.stringify(value)}\n\`\`\`\n`;
const SERIES = Array.from({ length: 60 }, (_, i) => `Series ${String(i + 1).padStart(2, '0')}`);
const lines = ['2024-01', '2024-02', '2024-03'].flatMap((date, m) => SERIES.map((series, s) => ({ date, series, value: 10 + s + m })));
const DETAIL = Array.from({ length: 60 }, (_, i) => `Detail ${String(i).padStart(2, '0')}`);
const point = (x: number, value: number) => Object.fromEntries([['x', x], ['value', value], ...DETAIL.map((d, i) => [d, `Original ${i}`])]);
const filler = Array.from({ length: 40 }, (_, i) => `Paragraph ${i + 1} keeps the page long enough to scroll.`).join('\n\n');
const source = '---\ntitle: Long readouts\nversion: "1"\n---\n\nReadouts longer than their charts.\n'
  + fence({ type: 'line', title: 'Sixty series', encoding: { x: 'date', y: 'value', color: 'series' }, data: { inline: lines } })
  + fence({ type: 'scatter', title: 'Sixty details', encoding: { x: 'x', y: 'value', detail: DETAIL }, data: { inline: [point(0, 1), point(10, 2)] } })
  + `\n${filler}\n`;

const h = await harness('long-readouts');
const inputs = await reports(h.dir, { only: [], extra: { readouts: source } });
const cases = [];
const errors: string[] = [];
const failures: string[] = [];
const check = async (label: string, fn: () => unknown) => {
  try {
    await fn();
    cases.push(label);
  } catch (error) {
    failures.push(`${label}: ${(error as Error).message}`);
  }
};

/** The readout's scroll state and its box against the visible room it may sit in. */
const state = (figure: Locator) => figure.evaluate(fig => {
  const r = fig.querySelector('.rv-chart__readout');
  const canvas = fig.querySelector('canvas.rv-chart__canvas')!.getBoundingClientRect();
  const f = canvas.width < 480 ? fig.getBoundingClientRect() : canvas;
  const frame = { left: Math.max(f.left, 0), top: Math.max(f.top, 0), right: Math.min(f.right, innerWidth), bottom: Math.min(f.bottom, innerHeight) };
  for (let parent = r!.parentElement; parent; parent = parent.parentElement) {
    const style = getComputedStyle(parent);
    const clips = (value: string) => ['hidden', 'clip', 'auto', 'scroll'].includes(value);
    const p = parent.getBoundingClientRect(), x = p.left + parent.clientLeft, y = p.top + parent.clientTop;
    if (clips(style.overflowX)) Object.assign(frame, { left: Math.max(frame.left, x), right: Math.min(frame.right, x + parent.clientWidth) });
    if (clips(style.overflowY)) Object.assign(frame, { top: Math.max(frame.top, y), bottom: Math.min(frame.bottom, y + parent.clientHeight) });
  }
  const box = r!.getBoundingClientRect();
  const last = r!.lastElementChild?.getBoundingClientRect();
  return {
    hidden: (r! as HTMLElement).hidden,
    top: r!.scrollTop,
    client: r!.clientHeight,
    height: r!.scrollHeight,
    heading: r!.querySelector('.rv-chart__readout-head')?.textContent ?? null,
    names: [...r!.querySelectorAll('.rv-chart__readout-line')].map(p => p.textContent),
    inset: [box.left - frame.left, box.top - frame.top, frame.right - box.right, frame.bottom - box.bottom],
    lastInView: last ? last.bottom <= box.bottom + 0.5 && last.top >= box.top - 0.5 : false,
    page: scrollY,
  };
});

try {
  for (const width of [1280, 390]) {
    const page = await h.browser.newPage({ viewport: { width, height: 900 }, reducedMotion: 'reduce' });
    watchErrors(page, errors);
    await page.goto(`${inputs.base}/readouts/report.html`);
    const models = await settle(page);
    const figures = page.locator('figure[data-rv-chart]');
    for (const [i, name] of [[0, 'line'], [1, 'scatter']] as const) {
      const at = `${name} @${width}`;
      const figure = figures.nth(i);
      const frame = figure.locator('.rv-chart__frame');
      await frame.focus();
      await page.keyboard.press('Home');
      await settle(page);
      const first = await state(figure);
      const model = models[i].geometry.panels[0].observations.slice().sort((a: { x: number; }, b: { x: number; }) => a.x - b.x)[0].readout;
      await check(`${at}: the readout is longer than the chart`, () => assert.ok(first.height > first.client + 20, JSON.stringify(first)));
      await check(`${at}: the readout stays 8 px inside the chart`, () => assert.ok(first.inset.every((d: number) => d >= 7.5), first.inset.join(', ')));
      await check(`${at}: every line of the model's readout, in order`, () => {
        assert.equal(first.heading, model.heading);
        assert.deepEqual(first.names, model.lines.map(l => `${l.name}${l.value}`));
      });
      if (name === 'line') {
        await check(`${at}: series in legend order`, () => assert.deepEqual(model.lines.map(l => l.name), SERIES));
      }
      const geometry = () => page.evaluate(k => JSON.stringify(window.__richview!.charts()[k].geometry), i);
      const before = await geometry();
      await page.keyboard.press('PageDown');
      const down = await state(figure);
      await check(`${at}: scrolling the readout leaves the chart's geometry alone`, async () => assert.equal(await geometry(), before));
      await check(`${at}: Page Down scrolls the readout`, () => assert.ok(down.top > 0, JSON.stringify(down)));
      await check(`${at}: Page Down keeps the selection and the page`, () => assert.deepEqual([down.heading, down.page], [first.heading, first.page]));
      for (let k = 0; k < 20; k++) await page.keyboard.press('PageDown');
      const end = await state(figure);
      await check(`${at}: Page Down reaches the last line`, () => {
        assert.ok(Math.abs(end.top - (end.height - end.client)) <= 1, JSON.stringify(end));
        assert.ok(end.lastInView);
      });
      await check(`${at}: still inside the chart at the end`, () => assert.ok(end.inset.every((d: number) => d >= 7.5), end.inset.join(', ')));
      for (let k = 0; k < 20; k++) await page.keyboard.press('PageUp');
      await check(`${at}: Page Up returns to the first line`, async () => assert.equal((await state(figure)).top, 0));
      // Tab leaves the chart; the scrolling readout is never a tab stop.
      await page.keyboard.press('Tab');
      await check(`${at}: Tab does not stop on the readout`, async () => assert.equal(await page.evaluate(() => document.activeElement?.classList.contains('rv-chart__readout') ?? false), false));
      await frame.focus();
      await page.keyboard.press('Home');
      await page.keyboard.press('PageDown');
      await page.keyboard.press('ArrowRight');
      await settle(page);
      const next = await state(figure);
      await check(`${at}: the next observation opens at its first line`, () => {
        assert.notEqual(next.heading, first.heading);
        assert.equal(next.top, 0);
      });
      // With the selection cleared there is no readout, and Page Down scrolls the page.
      await page.keyboard.press('Escape');
      await settle(page);
      const cleared = await state(figure);
      // Finish this deliberate native page scroll before resetting for the next chart.
      const scrolling = await page.evaluateHandle(() => {
        const state = { ended: false };
        const end = (event: Event) => {
          if (event.target !== document) return;
          state.ended = true;
          document.removeEventListener('scrollend', end);
        };
        document.addEventListener('scrollend', end);
        return { state, cancel: () => document.removeEventListener('scrollend', end) };
      });
      try {
        await page.keyboard.press('PageDown');
        await check(`${at}: without a readout Page Down scrolls the page`, async () => {
          assert.equal(cleared.hidden, true);
          await page.waitForFunction(({ before, scrolling }) => scrolling.state.ended && scrollY > before,
            { before: cleared.page, scrolling }, { timeout: 5_000 });
          assert.ok((await page.evaluate(() => scrollY)) > cleared.page);
        });
      } finally {
        await scrolling.evaluate(value => value.cancel());
        await scrolling.dispose();
      }
      await page.evaluate(() => scrollTo({ top: 0, behavior: 'instant' }));
    }
    // The expanded view (FEA-CH-44): the same readout, bounded by the dialog's chart.
    {
      const at = `expanded line @${width}`;
      await figures.nth(0).locator('.rv-chart__action--expand').click();
      const dialog = page.locator('dialog.rv-chart-dialog[open]');
      await dialog.waitFor();
      await settle(page);
      const expanded = dialog.locator('figure.rv-chart--expanded');
      await expanded.locator('.rv-chart__frame').focus();
      await page.keyboard.press('Home');
      const open = await state(expanded);
      await page.keyboard.press('PageDown');
      const scrolled = await state(expanded);
      await check(`${at}: the readout stays 8 px inside the expanded chart`, () => assert.ok(open.inset.every((d: number) => d >= 7.5), open.inset.join(', ')));
      await check(`${at}: Page Down scrolls a long readout and keeps the selection`, () => {
        if (open.height > open.client) assert.ok(scrolled.top > 0, JSON.stringify(scrolled));
        else assert.equal(scrolled.top, 0);
        assert.equal(scrolled.heading, open.heading);
      });
      await page.keyboard.press('Escape');
      await page.keyboard.press('Escape');
      await check(`${at}: Escape clears the selection, then closes the view`, async () => assert.equal(await page.locator('dialog.rv-chart-dialog[open]').count(), 0));
    }
    await page.close();
  }
  await check('no browser errors', () => assert.deepEqual(errors, []));
} finally {
  await inputs.close();
  await h.close();
}
if (failures.length) {
  console.error(failures.join('\n'));
  process.exit(1);
}
console.log(`PASS ${cases.length} long-readout cases: inside the chart, Page Down and Page Up through every line with the selection and page kept, the next observation from its first line, and page scrolling without a readout`);
